properties.JSON Schema:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "type": "object",
  "required": ["job_id", "ingestion", "storage_raw", "storage_preprocessed"],
  "properties": {
    "job_id": {
      "type": "string",
      "minLength": 1
    },
    "ingestion": {
      "type": "object",
      "required": ["source_type", "expected_sha1"],
      "properties": {
        "source_type": {
          "enum": ["HTTP", "LOCAL", "S3"]
        },
        "expected_sha1": {
          "type": "string",
          "pattern": "^[a-fA-F0-9]{40}$",
          "description": "Lo SHA1 atteso del file (40 caratteri esadecimali)"
        },
        "http_url": { "type": "string" },
        "local_path": { "type": "string" },
        "s3_source_bucket": { "type": "string" },
        "s3_source_key": { "type": "string" },
        "s3_source_region": { "type": "string" }
      },
      "allOf": [
        {
          "if": { "properties": { "source_type": { "const": "S3" } } },
          "then": { "required": ["s3_source_bucket", "s3_source_key", "s3_source_region"] }
        },
        {
          "if": { "properties": { "source_type": { "const": "HTTP" } } },
          "then": { "required": ["http_url"] }
        },
        {
          "if": { "properties": { "source_type": { "const": "LOCAL" } } },
          "then": { "required": ["local_path"] }
        }
      ]
    },
    "storage_raw": {
      "type": "object",
      "required": ["type"],
      "properties": {
        "type": { "enum": ["MINIO", "HDFS", "S3"] },
        "bucket": { "type": "string" },
        "path": { "type": "string" },
        "region": { "type": "string" }
      },
      "if": { "properties": { "type": { "enum": ["MINIO", "S3"] } } },
      "then": { "required": ["bucket", "region"] },
      "else": {
        "if": { "properties": { "type": { "const": "HDFS" } } },
        "then": { "required": ["path"] }
      }
    },
    "storage_preprocessed": {
      "type": "object",
      "required": ["type"],
      "properties": {
        "type": { "enum": ["HDFS", "S3"] },
        "path": { "type": "string" },
        "bucket": { "type": "string" },
        "region": { "type": "string" }
      },
      "if": { "properties": { "type": { "const": "S3" } } },
      "then": { "required": ["bucket", "path", "region"] },
      "else": {
        "if": { "properties": { "type": { "const": "HDFS" } } },
        "then": { "required": ["path"] }
      }
    }
  }
}
